package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;
public class FamilyChecks {
 static int n;static void check(boolean b,String msg){n++;if(!b)throw new AssertionError(msg);}
 static void slot(EntityVehicleF_Physics v,String type,Object part){Checks.Slot slot=new Checks.Slot();slot.types.add(type);v.definition.parts.add(slot);v.partsInSlots.add(part);}
 public static void main(String[]args){EntityVehicleF_Physics heli=new EntityVehicleF_Physics();heli.definition.systemName="bell47g";heli.definition.motorized.isAircraft=true;PartEngine engine=new PartEngine();engine.vehicleOn=heli;engine.damageVar.currentValue=75;slot(heli,"engine_helicopter_flat",engine);slot(heli,"propeller_rotor",null);slot(heli,"ground_skid_helicopter",null);check(FamilyWorkshop.kind(heli)==FamilyWorkshop.Kind.HELICOPTER,"helicopter based on native motor and rotor definitions");List<FamilyWorkshop.Target> rows=FamilyWorkshop.targets(heli);check(rows.get(0).label().equals("Fuselaje"),"helicopter structure label");check(rows.get(1).health()==50,"real engine damage shown");check(rows.get(2).label().startsWith("Rotor")&&rows.get(2).health()==null,"missing rotor shown as absent");check(rows.get(3).label().startsWith("Patin"),"landing skids recognized");EntityVehicleF_Physics boat=new EntityVehicleF_Physics();boat.definition.packID="otherpack";boat.definition.systemName="small_launch";slot(boat,"engine_boat",null);slot(boat,"propeller",null);check(FamilyWorkshop.kind(boat)==FamilyWorkshop.Kind.BOAT,"boat in another pack recognized");check(FamilyWorkshop.targets(boat).get(0).label().equals("Casco"),"hull uses actual total body condition");EntityVehicleF_Physics moto=new EntityVehicleF_Physics();moto.definition.systemName="custombike";slot(moto,"engine_car",null);slot(moto,"ground_wheel",null);slot(moto,"ground_wheel",null);check(FamilyWorkshop.kind(moto)==FamilyWorkshop.Kind.MOTORCYCLE,"two wheel motorcycle recognized");check(FamilyWorkshop.targets(moto).get(0).label().equals("Bastidor"),"motorcycle chassis label");EntityVehicleF_Physics plane=new EntityVehicleF_Physics();plane.definition.motorized.isAircraft=true;slot(plane,"engine_aircraft_horizontal",null);check(FamilyWorkshop.kind(plane)==FamilyWorkshop.Kind.PLANE,"airplane does not get boat GUI");Set<String> textures=new HashSet<>();for(Object v:List.of(heli,boat,moto,plane))textures.add(FamilyWorkshop.texture(v));check(textures.size()==4,"each vehicle family has unique texture");EntityVehicleF_Physics car=new EntityVehicleF_Physics();check(!FamilyWorkshop.special(car)&&FamilyWorkshop.texture(car).contains("workshop_car"),"car workshop retained");heli.engines.add(engine);engine.running=true;check(!FamilyWorkshop.stopped(heli),"running engine blocks repair");engine.running=false;heli.velocity=.1;check(!FamilyWorkshop.stopped(heli),"moving vehicle blocks repair");heli.velocity=0;check(FamilyWorkshop.stopped(heli),"stationary vehicle with motor off permits repair");InspectionChecks.Player player=new InspectionChecks.Player();player.eye=new Checks.Point(0,0,0);player.entity.now=0;Inspection.start(heli,player);player.entity.now=29;Inspection.tick(heli);check(player.packets.isEmpty(),"helicopter inspection waits full duration");player.entity.now=30;Inspection.tick(heli);check(player.packets.size()==1&&dev.survivorcreator.skills.Skills.total==5,"helicopter inspection opens GUI and grants Mechanics XP");check(!RoadDriving.transport(new PartSeat()),"seat interactions do not mistake part definitions for vehicles");System.out.println("Family workshop checks: "+n);}
}
